window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"i_N1bg8v3cI","speaker":"Guillaume","role":"Grand Duke","country":"Luxembourg","region":"Europe","url":"https://www.youtube.com/watch?v=i_N1bg8v3cI","date":"20260922","title":"🇱🇺 Luxembourg - Grand Duke Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1056,"words":2032,"counts":{"claims":28,"promises":2,"attacks":0},"topics":[{"topic":"UN reform","share":0.2409,"seconds":254},{"topic":"Youth program","share":0.1758,"seconds":186},{"topic":"UN cooperation","share":0.1319,"seconds":139},{"topic":"UN history","share":0.075,"seconds":79},{"topic":"Human rights","share":0.0658,"seconds":69},{"topic":"Luxembourg aid","share":0.0647,"seconds":68},{"topic":"Russia-Ukraine war","share":0.0642,"seconds":68},{"topic":"UN Security Council seat","share":0.0612,"seconds":65},{"topic":"Climate change","share":0.0608,"seconds":64},{"topic":"AI governance","share":0.0597,"seconds":63}],"timeline":[[0,64,null],[67,133,"UN cooperation"],[135,208,"UN cooperation"],[209,289,"UN history"],[290,358,"Russia-Ukraine war"],[360,422,"UN reform"],[423,488,"Youth program"],[490,553,"AI governance"],[553,617,"Youth program"],[618,687,"Luxembourg aid"],[689,754,"UN Security Council seat"],[754,824,"Human rights"],[826,893,"UN reform"],[895,959,"Climate change"],[960,1023,"UN reform"],[1026,1088,"UN reform"],[1089,1147,"Youth program"]],"stances":{"UN cooperation":"Grand Duke Guillaume states that trust is under strain but argues it is the necessary starting point for international achievements and reaffirms Luxembourg's commitment to the United Nations.","UN history":"Grand Duke Guillaume states that Luxembourg has historically believed in the principle of a new international order based on respect and common goals, citing its role as a founding member.","Russia-Ukraine war":"Grand Duke Guillaume states that Russia's war of aggression against Ukraine has brought war back to Europe and serves as a reminder that peace requires constant commitment.","UN reform":"Grand Duke Guillaume argues that while the multilateral system faces pressure and imperfections, it remains necessary and requires reform rather than abandonment.","Youth program":"Grand Duke Guillaume states that his experience as honorary chair of the World Scout Foundation reinforces his conviction in intergenerational dialogue and placing trust in young people.","AI governance":"Grand Duke Guillaume argues that technological progress must be guided by responsibility and place human beings at the center of decision-making.","Luxembourg aid":"Grand Duke Guillaume states that Luxembourg maintains a 1% national income allocation for development, builds partnerships with vulnerable countries, and remains committed to the multilateral humanitarian system.","UN Security Council seat":"Grand Duke Guillaume states that Luxembourg is seeking a seat on the UN Security Council for the 2031-2032 period based on its past experience and conviction that small countries can bridge divides.","Human rights":"Grand Duke Guillaume asserts that human rights are universal and not limited to specific cultures or political systems, emphasizing Luxembourg's commitment to defending them through multilateralism.","Climate change":"Grand Duke Guillaume states that climate change is a global challenge transcending borders and generations, requiring shared effort despite differing interests."},"claims":[{"t":107,"quote":"This is my first address to this assembly as head of state of the Grand Duchy of Luxembourg. I assumed office less than a year ago.","topic":"UN cooperation","kind":"fact"},{"t":146,"quote":"As a relatively young man who has had the privilege of traveling the world, I have been fortunate to meet people from very different cultures, backgrounds, and traditions.","topic":"UN cooperation","kind":"fact"},{"t":202,"quote":"There has never been a time when communication between people in different parts of the world was so easy.","topic":"UN cooperation","kind":"fact"},{"t":209,"quote":"Millions of young people have virtual friends and acquaintances across continents through social media, gaming, and countless other forms of connection.","topic":"UN history","kind":"fact"},{"t":279,"quote":"Luxembourg was among the 51 founding members that came together in San Francisco to lay the foundations of a new international order.","topic":"UN history","kind":"fact"},{"t":290,"quote":"At the time, we were the smallest country represented. We have prospered in the peace that Europe enjoyed for decades after 1945.","topic":"Russia-Ukraine war","kind":"fact"},{"t":323,"quote":"Russia's war of aggression against Ukraine has brought war back to our","topic":"Russia-Ukraine war","kind":"fact"},{"t":360,"quote":"81 years later that promise is under considerable pressure but it has not failed.","topic":"UN reform","kind":"fact"},{"t":405,"quote":"We often talk about young people as if they came from the future. Truth be told, they are already shaping the present.","topic":"UN reform","kind":"fact"},{"t":428,"quote":"This year, I had the privilege of succeeding his majesty King Kustaf of Sweden as honorary chair of the World Scout Foundation.","topic":"Youth program","kind":"fact"},{"t":471,"quote":"Artificial intelligence and other emerging technologies are already transforming our way of life and the way in which we work.","topic":"Youth program","kind":"fact"},{"t":490,"quote":"The current debates about the most extreme risks of AI remind us that technological progress cannot be divorced from responsibility.","topic":"AI governance","kind":"fact"},{"t":569,"quote":"Luxembourg supports the UN's youth delegate program as well as the United Nations youth office.","topic":"Youth program","kind":"fact"},{"t":578,"quote":"our commitment to education, science, and culture remains so important in particular through our term on the executive board of UNESCO for the period 2025 2029.","topic":"Youth program","kind":"fact"},{"t":618,"quote":"We continue to allocate 1% of our national income to development corporation.","topic":"Luxembourg aid","kind":"number"},{"t":659,"quote":"Protecting civilians and defending human cannot take a backseat to other Luxembourg has unstintingly worked to contribute to this effort through peacekeeping operations, humanitarian interventions, protecting children affected by armed conflict, the woman peace and security agenda as well as uh the mind clearance humanitarian activities in Ukraine.","topic":"Luxembourg aid","kind":"fact"},{"t":689,"quote":"The experience we gained as an elected member of the security council in 2013 and 2014 showed us that elected members can make a real difference","topic":"UN Security Council seat","kind":"fact"},{"t":708,"quote":"Luxembourg is asking for member states to place their trust in it as it seeks a security council seat for the 2031 2032 period","topic":"UN Security Council seat","kind":"fact"},{"t":775,"quote":"As a member of the human rights council for the period 2022 2024, took the full measure of just how important it is to defend human rights through multilateralism.","topic":"Human rights","kind":"fact"},{"t":789,"quote":"We continue to support the office of the high commissioner for human rights as well as efforts aimed at uh clarifying the fate of uh persons who were disappeared in Syria.","topic":"Human rights","kind":"fact"},{"t":859,"quote":"The purpose of institutions is to serve people.","topic":"UN reform","kind":"fact"},{"t":864,"quote":"Ultimately, the test of multilateralism is not how many resolutions we adopt or how many meetings we hold.","topic":"UN reform","kind":"fact"},{"t":927,"quote":"Small island developing states already experiences consequences that threaten their very existence.","topic":"Climate change","kind":"fact"},{"t":935,"quote":"Luxembourg may be landlocked, but we are deeply committed to this common effort, including by drawing on the expertise of our financial center in green finance.","topic":"Climate change","kind":"self_credit"},{"t":980,"quote":"Our experience has taught us that international law and multilateral institutions give countries, whatever their size, a voice and place at the","topic":"UN reform","kind":"fact"},{"t":1026,"quote":"We can look at the imperfections of multilateralism and conclude that it no longer works. or we can reform it fairly, strengthen it and make it worthy of the trust that future generations will place in us.","topic":"UN reform","kind":"fact"},{"t":1102,"quote":"Young people do not expect us to solve every challenge, but they do expect us to try.","topic":"Youth program","kind":"fact"},{"t":1109,"quote":"They expect us to act with And above all, they expect us not to lose faith in our ability to shape a better future.","topic":"Youth program","kind":"fact"}],"promises":[{"t":900,"quote":"Luxembourg will continue to defend because we know what happens when it Madame President, climate change reminds us perhaps more clearly than any other challenge that we cannot solve global problems by acting It transcends borders and generations.","topic":"Climate change","kind":"promise"},{"t":1123,"quote":"And that is the promise we should make to the next generation.","topic":"Youth program","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":0,"topic":null,"text":"of the Republic of Finland. The assembly will hear an address by His Royal Highness, Grand Duke Guom of Luxembourg. I request protocol to escort his Royal Highness and invite him to address the assembly. Madame President, excellencies, first and foremost, allow me to extend my warmest congratulations to his excellency Dr. Khaled Raman on his election as president of the General He can certainly count on Luxembourg's full support throughout his tenure. Madame President, the theme that has been chosen for this general debate can hardly be more timely."},{"t":67,"topic":"UN cooperation","text":"When I try to paint an honest picture of the world we live in, one thing strikes me in particular. Trust is under growing strain. trust between nations, trust between people, and perhaps most importantly, trust in our ability to work together. And yet, I believe that trust is precisely where we should begin. Not because trust is easy, but because every lasting achievement of the international community has begun with the decision to trust. This is my first address to this assembly as head of state of the Grand Duchy of Luxembourg. I assumed office less than a year ago. It is therefore a particular honor to stand before you today and to reaffirm from this podium the importance Luxembourg attaches to the United Nations and to a rule-based international order grounded in the rule of law."},{"t":135,"topic":"UN cooperation","text":"But this moment also makes me reflect on what the United Nations means from the perspective of my own generation. As a relatively young man who has had the privilege of traveling the world, I have been fortunate to meet people from very different cultures, backgrounds, and traditions. These experiences have left me with a simple and lasting conviction. We can learn a lot from each other. And I remain convinced that it is only by working together that we can overcome the many challenges our world is facing This conviction is not naive. I am fully aware of the difficulties confronting But precisely because the world is becoming more difficult, I believe we must resist the temptation to give up on There has never been a time when communication between people in different parts of the world was so easy."},{"t":209,"topic":"UN history","text":"Millions of young people have virtual friends and acquaintances across continents through social media, gaming, and countless other forms of connection. We have never been so connected, and yet we seem increasingly unable to trust one This should make us reflect. Is it still possible to build a world order in which respect and the willingness to work towards common goals can prevail over the pursuit of self-interests and power? I believe it is. But it will require dialogue, and a willingness to look beyond immediate interests. And this is why the United Nations matters. Madame President, Luxembourg has believed in this principle from the very 81 years ago, still deeply marked by the horrors of the Second World War, Luxembourg was among the 51 founding members that came together in San Francisco to lay the foundations of a new international order."},{"t":290,"topic":"Russia-Ukraine war","text":"At the time, we were the smallest country represented. We have prospered in the peace that Europe enjoyed for decades after 1945. And we have never forgotten that the peace could not be taken for granted. It was built generation after generation by those who chose cooperation over Today, that peace is being challenged once again. Russia's war of aggression against Ukraine has brought war back to our It is a stark reminder that peace requires constant commitment and that the principles on which our international order was built must be The United Nations itself was born from that choice. Its charter called upon us to unite our strength to maintain international peace and security and above all to save succeeding generations from the scourge of war."},{"t":360,"topic":"UN reform","text":"81 years later that promise is under considerable pressure but it has not failed. may be imperfect, but disenchantment should lead us to reform, not to The question is therefore not whether we still need multilateralism. The question is whether we have the courage to make it better. Madame la. Madame President, this brings me to a question that is very dear to my heart. What kind of world do we want to bequeath to future generations? We often talk about young people as if they came from the future. Truth be told, they are already shaping the present. Therefore, it is incumbent upon us to ask ourselves if we're really preparing a future that is going to earn their trust."},{"t":423,"topic":"Youth program","text":"My personal experience has done nothing but reinforce this conviction. This year, I had the privilege of succeeding his majesty King Kustaf of Sweden as honorary chair of the World Scout Foundation. My long-standing commitment to the scout movement has taught me a great deal about the power of uh intergenerational dialogue, solidarity, and the values of the scout movement. It's also taught me something absolutely fundamental. Placing our trust in young people means giving them responsibilities, allowing them to take action. They're growing up in a world in which there are extraordinary possibilities. But it's also a world where uncertainty runs deep. Artificial intelligence and other emerging technologies are already transforming our way of life and the way in which we work. The enthusiasm they give rise to also goes handinhand with the very real concerns."},{"t":490,"topic":"AI governance","text":"The current debates about the most extreme risks of AI remind us that technological progress cannot be divorced from responsibility. As we confront these transformations, we should endow our young people with the means to develop their critical thinking skills and their creativity. And this is exactly what education is supposed to do. transmit knowledge and competencies, but also to teach young people to call things into question to open up to others and to shoulder your responsibilities. Against this backdrop, I believe that we should have one guiding principle. Human beings should be at the heart of all of our decision-m we must protect the rights, security, and the well-being of all. We should also listen to young people, ask them what we can build. Working hand in hand through different cultures and generations."},{"t":553,"topic":"Youth program","text":"I saw for myself everything that young people are capable of accomplishing when we give them our trust. We give them responsibilities and the necessary space to take action as well as when we encourage them to work together. This is why Luxembourg supports the UN's youth delegate program as well as the United Nations youth office. It is also why our commitment to education, science, and culture remains so important in particular through our term on the executive board of UNESCO for the period 2025 2029. It is precisely these qualities which allow trust to flourish. Madame President, Luxembourg's commitment to the United Nations is underpinned by all three pillars. Peace and security, human rights and development. Solidarity must be translated into deeds."},{"t":618,"topic":"Luxembourg aid","text":"We continue to allocate 1% of our national income to development corporation. We are also building long-term partnerships with vulnerable countries. We remain committed to the multilateral humanitarian system as well as to all those who are providing assistance where it is most needed. The same level of responsibility applies to peace and Conflicts affect all human beings, women, children, older persons, persons with disabilities, as well as people who are already vulnerable. Protecting civilians and defending human cannot take a backseat to other Luxembourg has unstintingly worked to contribute to this effort through peacekeeping operations, humanitarian interventions, protecting children affected by armed conflict, the woman peace and security agenda as well as uh the mind clearance humanitarian activities in Ukraine."},{"t":689,"topic":"UN Security Council seat","text":"The experience we gained as an elected member of the security council in 2013 and 2014 showed us that elected members can make a real difference, especially when the permanent members of the security council are divided. It is for this reason that Luxembourg is asking for member states to place their trust in it as it seeks a security council seat for the 2031 2032 period. We do this humbly but firm in our conviction. Our conviction that a small country can offer up a different perspective, can bring different positions closer together and help find common ground. When this is particularly difficult, it is the same conviction which guides our commitment to human rights. At a time when respect for human rights is being subjected to growing pressures, we must resist the temptation to see it as something that's up for discussion."},{"t":754,"topic":"Human rights","text":"Human rights are neither a privilege reserved for the few nor the expression of one culture of one political system. They are the very bedrock of human Our commitment is also concrete. As a member of the human rights council for the period 2022 2024, took the full measure of just how important it is to defend human rights through multilateralism. We continue to support the office of the high commissioner for human rights as well as efforts aimed at uh clarifying the fate of uh persons who were disappeared in Syria. Madame President, restoring trust also means making our institutions worthy of that trust. The Security Council must become more representative, more effective, and more accountable to the entire membership of the United Nations."},{"t":826,"topic":"UN reform","text":"Africa in particular, and it was said many times today, should have a stronger And when the Security Council is the General Assembly must be able to play its rightful role. The United Nations must reform so that it can deliver more effectively, particularly when resources are But reform must never become an end in itself. The purpose of institutions is to serve people. Ultimately, the test of multilateralism is not how many resolutions we adopt or how many meetings we hold. It's whether a child is safer because of our decisions. Whether a young P person can receive an education. Whether a family can live in dignity, whether a small country can believe that international law will protect it when power alone cannot."},{"t":895,"topic":"Climate change","text":"This is why trust matters and this is why Luxembourg will continue to defend because we know what happens when it Madame President, climate change reminds us perhaps more clearly than any other challenge that we cannot solve global problems by acting It transcends borders and generations. Small island developing states already experiences consequences that threaten their very existence. Luxembourg may be landlocked, but we are deeply committed to this common effort, including by drawing on the expertise of our financial center in green finance. Our interests may differ, but our future is shared. Madame President, the world is becoming more fragmented."},{"t":960,"topic":"UN reform","text":"The international order is under strain. We need to recognize this reality, but we should not mistake a world of competing centers of power for a more just or stable international order. For Luxembourg, the answer is clear. Our experience has taught us that international law and multilateral institutions give countries, whatever their size, a voice and place at the It is not about resisting a changing world but to make multilateralism fit for that world. I believe this is ultimately what the United Nations asks of us. Not that we agree on everything. Not that we abandon our national interests, but that we recognize that there are challenges for which no nation, however powerful, can find lasting solutions alone."},{"t":1026,"topic":"UN reform","text":"We can look at the imperfections of multilateralism and conclude that it no longer works. or we can reform it fairly, strengthen it and make it worthy of the trust that future generations will place in us. I know which choice I want to make because this is the world I want to leave to my children. A world where dialogue is stronger than confrontation. Where respect between nations allows differences to become sources of strength rather than division. Where international law protects weaks protects the weak as well as the strong. If we restore trust, if we listen to the next generation, and if we have the courage to act together, the United Nations can continue to be more than a reflection of the world as it is."},{"t":1089,"topic":"Youth program","text":"It can remain an instrument for building the world we want to leave a world worthy of the trust of those who will inherit it. Young people do not expect us to solve every challenge, but they do expect us to try. They expect us to act with And above all, they expect us not to lose faith in our ability to shape a better future. And that is the promise we should make to the next generation. Thank you. On behalf of the assembly, I wish to thank the Grand Duke of Luxembourg. The assembly will hear an address by his"}],"compare":[{"topic":"UN & its reform","share":0.509,"mean":0.2032,"rank":5,"others":170},{"topic":"Youth","share":0.1758,"mean":0.0015,"rank":1,"others":5},{"topic":"Human Rights","share":0.0658,"mean":0.0083,"rank":8,"others":24},{"topic":"Russia-Ukraine War","share":0.0642,"mean":0.0352,"rank":39,"others":44},{"topic":"Climate Change","share":0.0608,"mean":0.0427,"rank":55,"others":77},{"topic":"Artificial Intelligence","share":0.0597,"mean":0.0504,"rank":65,"others":83}]};
